import{_ as o}from"./chunks/Audio.COine8Wh.js";import{_ as i}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as r,j as e,G as t,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"Rural Broadband Protection Act of 2025","description":"","frontmatter":{"legisId":"2026-05-11-rural-broadband-protection-act-of-2025","title":"Rural Broadband Protection Act of 2025","displayTitle":"Rural Broadband Protection Act of 2025","lawNumber":"119-89","billNumber":"S. 98","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ89.xml","publishDate":"2026-05-11T00:00:00-05:00","industries":["technology","government-operations"],"agencies":["Federal Communications Commission"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Rural Broadband Protection Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-11-rural-broadband-protection-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Rural Broadband Protection Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-11-rural-broadband-protection-act-of-2025\\",\\"datePublished\\":\\"2026-05-11T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-11-rural-broadband-protection-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-05-11-rural-broadband-protection-act-of-2025.md","filePath":"congress-bills/2026-05-11-rural-broadband-protection-act-of-2025.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-05-11-rural-broadband-protection-act-of-2025.md"},g=Object.assign(d,{setup(c){return(p,a)=>(r(),n("div",null,[a[0]||(a[0]=e("h1",{id:"rural-broadband-protection-act-of-2025",tabindex:"-1"},[l("Rural Broadband Protection Act of 2025 "),e("a",{class:"header-anchor",href:"#rural-broadband-protection-act-of-2025","aria-label":'Permalink to "Rural Broadband Protection Act of 2025"'},"​")],-1)),t(o),t(i,{list:"/congress-bills"}),a[1]||(a[1]=s('<p>Signed into law on Monday, May 11, 2026. Public Law 119-89, S. 98.</p><p><strong>Headline:</strong> New FCC vetting will limit rural broadband funding to applicants that can credibly build and operate their proposed networks.</p><p><strong>Why it matters:</strong> The law aims to protect high-cost universal service funding from failed projects by screening applicants’ capabilities, plans, and past compliance.</p><p><strong>What the law does:</strong></p><ul><li>Requires the FCC to begin rulemaking within 180 days to create a vetting process for prospective funding recipients.</li><li>Requires applicants to document their technical, financial, and operational ability and provide a reasonable business plan.</li><li>Directs the FCC to apply established standards without favoring any technology and to consider applicants’ compliance in government broadband programs.</li><li>Requires penalties of at least $9,000 per pre-authorization default violation, with a base forfeiture generally no lower than 30 percent of total support.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Applicants and prospective recipients seeking new high-cost universal service funding for broadband deployment.</li><li>Rural communities served by federally supported broadband networks.</li><li>The Federal Communications Commission.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Rural residents may have greater assurance that funded broadband providers can complete and operate promised networks.</li><li>Broadband applicants will face more documentation, compliance review, and financial consequences for defaulting.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="rural-broadband-protection-act-of-2025-1" tabindex="-1">Rural Broadband Protection Act of 2025 <a class="header-anchor" href="#rural-broadband-protection-act-of-2025-1" aria-label="Permalink to &quot;Rural Broadband Protection Act of 2025&quot;">​</a></h3><p>This law requires the Federal Communications Commission to create a vetting process for applicants and other prospective recipients seeking new high-cost universal service funding to deploy broadband networks. Funding may go only to applicants that demonstrate the technical, financial, and operational ability and a reasonable business plan to build the proposed network and provide the promised services.</p><p><strong>Key takeaways:</strong></p><ul><li>The FCC must begin a rulemaking to establish the vetting process within 180 days after enactment.</li><li>Applicants must provide enough detail and documentation for the FCC to assess their capabilities and business plans.</li><li>The FCC must evaluate applicants using established technical, financial, and operational standards while remaining neutral among technologies.</li><li>The FCC must consider each applicant’s compliance history in FCC and other government broadband funding programs.</li><li>The FCC must establish penalties for defaults before authorization of at least $9,000 per violation, with a base forfeiture generally no lower than 30 percent of the applicant’s total support.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ89.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ89.xml</a></p>',15))]))}});export{m as __pageData,g as default};
